use vstd::prelude::*;

verus! {

fn is_greater(n: i32, a: &[i32]) -> (result: bool)
    ensures
        // result is true exactly when n > a[j] for all valid indices j
        result == forall |j: usize| j < a.len() ==> n > a[j],
    ensures
        // if result is false then there is some index j with a[j] >= n
        !result ==> exists |j: usize| j < a.len() && a[j] >= n,
{
    let mut i: usize = 0;
    // We scan until either i == a.len() or we find an element >= n.
    while i < a.len()
        invariant
            // i always in [0, a.len()]
            i <= a.len(),
            // for all scanned indices j < i, we have n > a[j]
            forall |j: usize| j < i ==> n > a[j],
        decreases
            // measure decreases each iteration
            a.len() - i,
    {
        if a[i] < n {
            // element at i satisfies the strict inequality, advance
            i = i + 1;
        } else {
            // found a[i] >= n, break out
            break;
        }
    }

    if i == a.len() {
        // scanned entire array without finding a violation
        result = true;
    } else {
        // here 0 <= i < a.len() and a[i] >= n
        assert(a[i] >= n);
        result = false;
    }
}

} // verus!

